import re
from taf.ul.sc.enb.generic_enb import GenericEnb
from moler.util.moler_test import MolerTest


class Fzp(GenericEnb):
    def __init__(self,
                 unix,                  # type: 'FzpFunctionality'
                 console=None,          # type: 'Optional[FzpFunctionality]'
                 ):
        """

        :param unix: connection via ssh
        :param console: connection to FZM console via telnet
        """

        self.unix = unix
        self.console = console

        super(Fzp, self).__init__(enb=unix, base_state='LINUX')
        self._is_mini_macro_unit = None
        self._is_mbo_hardware = None  # Multi Band Outdoor
        self._is_dbi_hardware = None  # Dual Band Indoor

    @property
    def is_mini_macro_unit(self):
        if self._is_mini_macro_unit is None:
            self.__is_mini_macro_unit()
        return self._is_mini_macro_unit

    def __is_mini_macro_unit(self):
        """
        Check whether mini macro is unit hardware.
        :return: `True` if command was successful, `False` otherwise
        :rtype: bool
        """
        _mm_hardware_regex = r"^(FW2CA)$"

        if self.hardware_product_code and re.search(_mm_hardware_regex, self.hardware_product_code):
            self._is_mini_macro_unit = True
        else:
            self._is_mini_macro_unit = False

        return self._is_mini_macro_unit

    @property
    def is_mbo_hardware(self):
        if self._is_mbo_hardware is None:
            self.__is_mbo_hardware()
        return self._is_mbo_hardware

    def __is_mbo_hardware(self):
        """
        Check if is MultiBandOutdoor unit.
        :return: `True` if command was successful, `False` otherwise
        :rtype: bool
        """
        cmd_devmem = self.unix.device.get_cmd(cmd_name="devmem",
                                              cmd_params={"address": "0x01f50000"})
        cmd_result = cmd_devmem()

        if cmd_result["VALUE"] == "0x00000000":
            self._is_mbo_hardware = True
        else:
            self._is_mbo_hardware = False

        return self._is_mbo_hardware

    @property
    def is_dbi_hardware(self):
        if self._is_dbi_hardware is None:
            self.__is_dbi_hardware()
        return self._is_dbi_hardware

    def __is_dbi_hardware(self):
        """
        Check if is DualBandIndoor unit.
        :return: `True` if command was successful, `False` otherwise
        :rtype: bool
        """
        _dbi_hardware_regex = r"^FW2"

        if self.hardware_product_code and \
                re.search(_dbi_hardware_regex, self.hardware_product_code) and \
                not self.is_mbo_hardware:
            self._is_dbi_hardware = True
        else:
            self._is_dbi_hardware = False

        return self._is_dbi_hardware

    def _set_digital_link(self, value, link_number):
        """
        Helper method for main enable or disable gigital link.
        :param value: Action value, where 1 equals enable and 0 equals disable.
        :param link_number: number of link
        :return: None
        :rtype: None
        """
        address = '0x140800'
        if link_number == 2:
            address = '0x240800'

        self._set_fpgamem(address=address, value=value)

    def _set_digital_domain(self, value, cells_connected_via_obsai=[]):
        """
        Helper method for main enable or disable Small Cell digital domain methods.
        This method uses _set_digital_link() helper method.
        :param value: Action value, where 1 equals enable and 0 equals disable.
        :param cells_connected_via_obsai: list of enb cell connected via obsai with UE simulator
        :return: None
        :rtype: None
        """

        if len(cells_connected_via_obsai) == 0:
            return

        enabling_first_link_is_needed = self._is_enabling_first_link_needed(cells_connected_via_obsai)
        enabling_second_link_is_needed = self._is_enabling_second_link_needed(cells_connected_via_obsai)

        if enabling_first_link_is_needed:
            self._set_digital_link(value, link_number=1)
        if enabling_second_link_is_needed:
            self._set_digital_link(value, link_number=2)

    @staticmethod
    def _is_enabling_first_link_needed(cells_connected_via_obsai):
        """
        Determine if enabling firs link is needed
        :param cells_connected_via_obsai: list of enb cell connected via obsai with UE simulator
        :return: `True` if first cell is connected via obsai, `False` otherwise
        :rtype: bool
        """
        if 1 in cells_connected_via_obsai:
            return True
        return False

    def _is_enabling_second_link_needed(self, cells_connected_via_obsai):
        """
        Determine if enabling firs link is needed
        :param cells_connected_via_obsai: list of enb cell connected via obsai with UE simulator
        :return: `True` or 'False'
        :rtype: bool
        """
        if self.is_dbi_hardware and 3 in cells_connected_via_obsai:
            return True
        if not self.is_dbi_hardware and not self.is_mbo_hardware and 2 in cells_connected_via_obsai:
            return True
        return False

    def _set_fpgamem(self, address, value):
        """
        Helper method for _set_digital_domain() method.
        Goes to LINUX state.
        Performs fpgamem command with given address and value parameter.
        :param value: Action value, where 1 equals enable and 0 equals disable.
        :return: None
        :rtype: None
        """
        self.unix.device.goto_state(self.base_state)
        cmd_fpgamem = self.unix.device.get_cmd(cmd_name="fpgamem",
                                               cmd_params={"address": address,
                                                           "value": value})
        cmd_fpgamem()

    def enable_digital_domain(self, cells_connected_via_obsai=[]):
        """
        Enable Small Cell digital domain.
        Uses _set_digital_domain() helper method.
        :return: None
        :rtype: None
        """
        self._set_digital_domain(value=1, cells_connected_via_obsai=cells_connected_via_obsai)

    def disable_digital_domain(self, cells_connected_via_obsai=[]):
        """
        Disable Small Cell digital domain.
        Uses _set_digital_domain() helper method.
        :return: None
        :rtype: None
        """
        self._set_digital_domain(value=0, cells_connected_via_obsai=cells_connected_via_obsai)

    def _set_devmem(self, address, value):
        """
        Helper method for disable_and_enable_rx_sync() method.
        Goes to LINUX state and check whether eNB is DBI hardware.
        Performs turn on and off operation.
        :param address: Value
        :param value: Address
        :return: None
        :rtype: None
        """
        self.unix.device.goto_state(self.base_state)

        cmd_devmem = self.unix.device.get_cmd(cmd_name="devmem",
                                              cmd_params={"address": address,
                                                          "value": value,
                                                          "size": 32})
        cmd_devmem()

    def _disable_and_enable_rx_sync(self, address):
        """
        Turn off and turn on sync on RX eNB.
        Uses _set_devmem() helper method.
        :return: None
        :rtype: None
        """

        self._set_devmem(address=address, value="0x2001")
        MolerTest.sleep(seconds=7)
        self._set_devmem(address=address, value="0x2003")

    def disable_and_enable_rx_sync(self, cell_connected_via_obsai=[]):
        """
        Turn off and turn on sync on RX eNB.
        Uses _set_devmem() helper method.
        :return: None
        :rtype: None
        """
        if self.is_dbi_hardware or self.is_mbo_hardware:
            self._disable_and_enable_rx_sync(address="0x01f52000")
            if 3 in cell_connected_via_obsai:
                address = '0x01f50000' if self.is_mbo_hardware else '0x01f52800'
                self._disable_and_enable_rx_sync(address=address)
